 * respect string literals, quoted identifiers and comments, and — crucially —
 * keeps a `CREATE TRIGGER ... BEGIN ... END;` body together as a single statement
 * even though it contains its own semicolon-terminated sub-statements.
 */

// Matches the leading tokens of a trigger definition:
//   CREATE TRIGGER ...
//   CREATE TEMP TRIGGER ... / CREATE TEMPORARY TRIGGER ...
//   EXPLAIN CREATE TRIGGER ... (optionally EXPLAIN QUERY PLAN ...)
const TRIGGER_START =
    /^(?:EXPLAIN\b(?:\s+QUERY\s+PLAN\b)?\s+)?CREATE\s+(?:(?:TEMP|TEMPORARY)\s+)?TRIGGER\b/i;

function isWhitespace(ch) {
    return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === '\v';
}

function isWordStart(ch) {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_';
}

function isWordChar(ch) {
    return isWordStart(ch) || (ch >= '0' && ch <= '9');
}

// `i` points at the opening quote. Returns the index just past the closing quote,
// handling SQL's doubled-quote escaping (e.g. 'it''s'). Backtick and double-quote
// identifiers use the same doubling rule.
function skipString(sql, i) {
    const quote = sql[i];
    const n = sql.length;
    let j = i + 1;
    while (j < n) {
        if (sql[j] === quote) {
            if (sql[j + 1] === quote) {
                j += 2; // escaped quote — stays inside the literal
                continue;
            }
            return j + 1;
        }
        j++;
    }
    return n; // unterminated literal — consume to end
