// `i` points at the leading '-' of a `--` line comment. Returns the index of the
// terminating newline (or end of input); the newline itself is handled as normal
// whitespace by the caller.
function skipLineComment(sql, i) {
    const n = sql.length;
    let j = i + 2;
    while (j < n && sql[j] !== '\n') j++;
    return j;
}

// `i` points at the leading '/' of a `/* */` block comment. Returns the index just
// past the closing `*/` (or end of input for an unterminated comment).
function skipBlockComment(sql, i) {
    const n = sql.length;
    let j = i + 2;
    while (j < n && !(sql[j] === '*' && sql[j + 1] === '/')) j++;
