/**
 * Splits a SQL string into an array of individual SQL statement strings.
 *
 * Each returned statement has its surrounding whitespace trimmed; whitespace
 * internal to a statement (newlines, indentation) is preserved exactly. Trigger
 * definitions with a BEGIN...END body are returned as a single element regardless
 * of how many semicolon-terminated statements appear inside the body. A bare END
 * outside of any string literal terminates the trigger; the word END appearing
 * inside a string literal is ignored.
 *
 * @param {string} sql
 * @returns {string[]}
 */
export function splitStatements(sql) {
    const statements = [];
    if (typeof sql !== 'string' || sql.length === 0) {
        return statements;
    }

    const n = sql.length;
    let i = 0;
    let stmtStart = 0;      // start offset of the statement currently being scanned
    let sawContent = false; // whether any non-ws/non-comment content has been seen yet
    let isTrigger = false;  // whether the current statement is a trigger definition
    // Trigger scan phases: 0 = before BEGIN, 1 = inside body (BEGIN seen, END not),
    // 2 = END seen (waiting for the terminating semicolon).
