        // semicolon or the word END inside them has no structural meaning.
        if (ch === "'" || ch === '"' || ch === '`') {
            if (!sawContent) {
                stmtStart = i;
                sawContent = true;
                isTrigger = false; // a statement can't start with a string literal
            }
            i = skipString(sql, i);
            continue;
        }

        if (!sawContent) {
            if (isWhitespace(ch)) {
                i++;
                continue;
            }
            // First real content of a statement — decide once whether it is a trigger.
            stmtStart = i;
            sawContent = true;
            isTrigger = TRIGGER_START.test(sql.slice(i));
            phase = 0;
